   - confiscate_fish.json  
   - count_fish.json
   - deposit_catch.json
   - impose_penalty.json
   - non_fisher_withdrawal.json
   - record_consumption.json
   - report_catch.json
   - set_fine.json
   - submit_shortfall.json
   - tally_catches.json
   - vote_restoration.json
   - vote_sanctions.json

